-- Preparación de investigación documental para Supabase.
-- No requiere PostGIS. No establece coordenadas ni nivel de riesgo.
-- Todas las geometrías y coordenadas del conjunto actual son NULL.

begin;

create table if not exists public.documented_episodes (
  id text primary key,
  event_date date,
  date_precision text not null,
  localities text not null,
  neighborhoods text not null,
  location_description text not null,
  location_precision text not null,
  longitude double precision,
  latitude double precision,
  geometry jsonb,
  event_type text not null,
  evidence_summary text not null,
  documentary_confidence text not null check (documentary_confidence in ('alta','media','baja','mixta')),
  source_mentions jsonb not null check (jsonb_typeof(source_mentions) = 'array'),
  constraint documented_episodes_coordinate_pair check ((longitude is null) = (latitude is null)),
  constraint documented_episodes_longitude_range check (longitude is null or longitude between -180 and 180),
  constraint documented_episodes_latitude_range check (latitude is null or latitude between -90 and 90),
  constraint documented_episodes_point_geometry check (geometry is null or geometry ->> 'type' = 'Point')
);

create table if not exists public.interest_sectors (
  id text primary key,
  localities text not null,
  neighborhood text not null,
  sector_type text not null,
  location_description text not null,
  location_precision text not null,
  longitude double precision,
  latitude double precision,
  geometry jsonb,
  episode_ids text not null,
  source_mention_ids text not null,
  constraint interest_sectors_coordinate_pair check ((longitude is null) = (latitude is null)),
  constraint interest_sectors_longitude_range check (longitude is null or longitude between -180 and 180),
  constraint interest_sectors_latitude_range check (latitude is null or latitude between -90 and 90),
  constraint interest_sectors_point_geometry check (geometry is null or geometry ->> 'type' = 'Point')
);

create index if not exists documented_episodes_event_date_idx on public.documented_episodes (event_date desc);
create index if not exists interest_sectors_locality_idx on public.interest_sectors (localities);
create index if not exists interest_sectors_neighborhood_idx on public.interest_sectors (neighborhood);

alter table public.documented_episodes enable row level security;
alter table public.interest_sectors enable row level security;
drop policy if exists "read documented episodes" on public.documented_episodes;
create policy "read documented episodes" on public.documented_episodes for select to anon, authenticated using (true);
drop policy if exists "read interest sectors" on public.interest_sectors;
create policy "read interest sectors" on public.interest_sectors for select to anon, authenticated using (true);
grant select on public.documented_episodes, public.interest_sectors to anon, authenticated;

-- Vista de lectura estable para React. Deck.gl debe ignorar filas con longitud/latitud NULL.
create or replace view public.map_documented_episodes with (security_invoker = true) as
select
  id,
  event_date,
  date_precision,
  localities,
  neighborhoods,
  location_description,
  location_precision,
  longitude,
  latitude,
  geometry,
  event_type,
  evidence_summary,
  documentary_confidence,
  source_mentions
from public.documented_episodes;
grant select on public.map_documented_episodes to anon, authenticated;

-- Episodios documentados: upsert por ID para permitir reejecutar este archivo.

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2012-12-06', '2012-12-06', 'fecha de nota; episodio ese día', 'Tigre; Benavídez; General Pacheco; El Talar; Troncos del Talar', 'Las Tunas; La Paloma; no especificado', 'Colectora Alfredo Palacios y calles laterales (Troncos); Corrientes (Pacheco); otros barrios sin calle', 'mixta: algunas calles nombradas, barrios sin punto', NULL, NULL, NULL, 'anegamiento por lluvias', 'Múltiples reportes vecinales de calles inundadas en distintas localidades durante una misma lluvia; las menciones de cruces no asignan localidades inequívocamente.', 'mixta', '[{"mention_id":"TIG-2012-001","locality":"Tigre","neighborhood":"Las Tunas","location_description":"Barrio Las Tunas (sin calle indicada)","event_date_as_reported":"2012-12-06","event_type":"anegamiento por lluvias","evidence":"Artículo recoge reportes vecinales que identifican Las Tunas entre los barrios complicados; no precisa calles.","documentary_confidence":"media","source_title":"Clarín Zonal Tigre","source_url":"https://www.clarin.com/zonales/tigre/calles-inundadas_0_HJlw4vWeWQ.html"},{"mention_id":"TIG-2012-002","locality":"Benavídez","neighborhood":"No especificado","location_description":"Localidad de Benavídez (sin calle indicada)","event_date_as_reported":"2012-12-06","event_type":"anegamiento por lluvias","evidence":"El artículo identifica Benavídez entre las zonas con calles anegadas a partir de avisos vecinales; sin dirección puntual.","documentary_confidence":"media","source_title":"Clarín Zonal Tigre","source_url":"https://www.clarin.com/zonales/tigre/calles-inundadas_0_HJlw4vWeWQ.html"},{"mention_id":"TIG-2012-003","locality":"General Pacheco","neighborhood":"No especificado","location_description":"Calle Corrientes; cruces mencionados sin asignación inequívoca","event_date_as_reported":"2012-12-06","event_type":"anegamiento por lluvias","evidence":"El artículo menciona calle Corrientes en Pacheco y varios cruces anegados en la misma nota, pero no vincula inequívocamente esos cruces con esta calle.","documentary_confidence":"baja","source_title":"Clarín Zonal Tigre","source_url":"https://www.clarin.com/zonales/tigre/calles-inundadas_0_HJlw4vWeWQ.html"},{"mention_id":"TIG-2012-004","locality":"El Talar","neighborhood":"La Paloma","location_description":"Barrio La Paloma (sin calle indicada)","event_date_as_reported":"2012-12-06","event_type":"anegamiento por lluvias","evidence":"El artículo incluye La Paloma en El Talar entre los sectores afectados según reportes vecinales.","documentary_confidence":"media","source_title":"Clarín Zonal Tigre","source_url":"https://www.clarin.com/zonales/tigre/calles-inundadas_0_HJlw4vWeWQ.html"},{"mention_id":"TIG-2012-005","locality":"Troncos del Talar","neighborhood":"No especificado","location_description":"Colectora Alfredo Palacios y calles laterales","event_date_as_reported":"2012-12-06","event_type":"anegamiento por lluvias","evidence":"Testimonio vecinal citado por el artículo describe la colectora y calles laterales totalmente inundadas.","documentary_confidence":"media","source_title":"Clarín Zonal Tigre","source_url":"https://www.clarin.com/zonales/tigre/calles-inundadas_0_HJlw4vWeWQ.html"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2014-03-04', '2014-03-04', 'día anterior a nota del 5/3/2014', 'Tigre; General Pacheco; Ricardo Rojas', 'Las Tunas; El Garrote; San Lorenzo', 'Entorno del arroyo Las Tunas; El Garrote (Carupá); puente de calle Paul Groussac hacia Ruta 9', 'mixta: puente/calle nombrada y sectores amplios', NULL, NULL, NULL, 'desborde de arroyo y anegamiento por tormenta', 'Tormenta de marzo de 2014 con anegamientos reportados en distintos barrios. Se consolidan aquí tres menciones del mismo episodio. Sin calles precisas para varios sectores.', 'media', '[{"mention_id":"TIG-2013-001","locality":"Tigre","neighborhood":"Las Tunas","location_description":"Barrio Las Tunas y entorno del arroyo Las Tunas (sin calle indicada)","event_date_as_reported":"2014-03-04","event_type":"desborde de arroyo y anegamiento","evidence":"Nota publicada el 5 de marzo informa desborde del arroyo Las Tunas y anegamientos de calles y viviendas durante la tormenta del día anterior.","documentary_confidence":"media","source_title":"Tiempo Argentino (edición PDF)","source_url":"https://www.tiempoar.com.ar/wp-content/uploads/2021/04/1372-1.pdf"},{"mention_id":"TIG-2013-002","locality":"General Pacheco","neighborhood":"El Garrote","location_description":"Barrio El Garrote en Carupá (sin calle indicada)","event_date_as_reported":"2014-03-04","event_type":"anegamiento por tormenta","evidence":"La nota del 5 de marzo cita a un concejal que incluye El Garrote entre los sectores más afectados; ubicación general, sin dirección.","documentary_confidence":"media","source_title":"Tiempo Argentino (edición PDF)","source_url":"https://www.tiempoar.com.ar/wp-content/uploads/2021/04/1372-1.pdf"},{"mention_id":"TIG-2013-004","locality":"Ricardo Rojas","neighborhood":"San Lorenzo","location_description":"Paso/puente de calle Paul Groussac hacia Ruta 9","event_date_as_reported":"2014-03-04","event_type":"anegamiento y reclamo vecinal","evidence":"Reporte periodístico sobre la tormenta refiere corte del puente de Paul Groussac por vecinos del barrio San Lorenzo en demanda de soluciones; no documenta coordenadas ni profundidad.","documentary_confidence":"media","source_title":"La Generación Siguiente (reproduce declaraciones atribuidas a un concejal)","source_url":"https://lageneracionsiguiente.blogspot.com/2014/03/ya-son-mas-de-cien-mil-inundados-de.html"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2013-05', NULL, 'fecha exacta desconocida', 'General Pacheco', 'Las Tunas', 'Barrio y entorno del arroyo Las Tunas', 'aproximada: barrio/arroyo, sin dirección', NULL, NULL, NULL, 'anegamiento por lluvias; fecha exacta desconocida', 'Crónica de reclamo vecinal relata agua hasta las rodillas tras lluvias, pero no fija fecha precisa del episodio; no se toma la fecha de publicación como fecha del evento.', 'media', '[{"mention_id":"TIG-2013-003","locality":"General Pacheco","neighborhood":"Las Tunas","location_description":"Barrio Las Tunas y entorno del arroyo (sin calle indicada)","event_date_as_reported":"2013-05-30","event_type":"anegamiento por lluvias","evidence":"Crónica de reclamo vecinal del 30 de mayo relata agua hasta las rodillas tras lluvias y anegamientos recurrentes; no identifica una calle concreta.","documentary_confidence":"media","source_title":"PTS","source_url":"https://www.pts.org.ar/Barrio-Las-Tunas-lo-que-la-lluvia-nos-dejo"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2015-06-30', '2015-06-30', 'inferida por relato de jornada previa en nota 1/7/2015', 'Benavídez; General Pacheco', 'El Arco; López Camelo; Las Tunas', 'Gorriti y Fulminante (El Arco); entorno delimitado por Quintana, Dorrego y arroyo tributario de Las Tunas (López Camelo); calles bajas de Las Tunas', 'mixta: una intersección nombrada y sectores amplios', NULL, NULL, NULL, 'desborde de arroyo y anegamiento de viviendas/calles', 'Una misma crónica documenta viviendas/calles afectadas y un desborde de arroyo en tres sectores. La fecha se infiere del texto, no es una marca temporal observada.', 'media', '[{"mention_id":"TIG-2015-001","locality":"Benavídez","neighborhood":"El Arco","location_description":"Esquina de Gorriti y Fulminante","event_date_as_reported":"2015-06-30","event_type":"anegamiento de vivienda y calles","evidence":"Crónica del 1 de julio informa que una vecina documentó su vivienda llena de agua; la fecha del evento se infiere del texto «hoy» y del agua ya bajando «ayer».","documentary_confidence":"media","source_title":"Agencia Popular de Comunicación","source_url":"https://agencia-popular.com/2015/07/01/tigre-volvio-a-inundarse-y-los-vecinos-le-exigieron-soluciones-a-zamora/"},{"mention_id":"TIG-2015-002","locality":"General Pacheco","neighborhood":"López Camelo","location_description":"Entorno entre arroyo tributario de Las Tunas y calles Quintana y Dorrego","event_date_as_reported":"2015-06-30","event_type":"desborde de arroyo y anegamiento de viviendas","evidence":"La crónica del 1 de julio informa que el arroyo desbordó e inundó calles y algunas casas del barrio. La fecha se infiere del relato de la jornada previa.","documentary_confidence":"media","source_title":"Agencia Popular de Comunicación","source_url":"https://agencia-popular.com/2015/07/01/tigre-volvio-a-inundarse-y-los-vecinos-le-exigieron-soluciones-a-zamora/"},{"mention_id":"TIG-2015-003","locality":"General Pacheco","neighborhood":"Las Tunas","location_description":"Barrio Las Tunas (calles bajas; sin nombres)","event_date_as_reported":"2015-06-30","event_type":"anegamiento de calles","evidence":"Vecina citada en crónica del 1 de julio informa que se anegaron las calles y el barrio quedó aislado por horas; fecha inferida de la referencia a la jornada previa.","documentary_confidence":"media","source_title":"Agencia Popular de Comunicación","source_url":"https://agencia-popular.com/2015/07/01/tigre-volvio-a-inundarse-y-los-vecinos-le-exigieron-soluciones-a-zamora/"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2015-08', NULL, 'fecha aproximada: primera semana de agosto 2015; nota 7/8/2015', 'Benavídez; Rincón de Milberg', 'Esperanza; La Mascota; Malvinas; no especificado', 'Sectores residenciales; sin calles indicadas', 'aproximada: barrios/localidades, sin dirección', NULL, NULL, NULL, 'inundación por lluvias intensas', 'Crónica reporta viviendas afectadas por lluvias en Benavídez y Rincón. No permite asegurar el día exacto del evento; se conserva mes/intervalo en vez de un día fabricado.', 'media', '[{"mention_id":"TIG-2015-004","locality":"Benavídez","neighborhood":"Barrios Esperanza, La Mascota y Malvinas","location_description":"Sectores barriales (sin calles indicadas)","event_date_as_reported":"2015-08-06","event_type":"inundación por lluvias intensas","evidence":"Crónica atribuye a Télam/funcionarios municipales afectación de viviendas en estos barrios durante las lluvias; sin coordenadas ni calle concreta.","documentary_confidence":"media","source_title":"La Arena (reporte basado en Télam y declaraciones municipales)","source_url":"https://www.laarena.com.ar/el-pais/2015-8-7-7-25-0-tigre-y-lujan-bajo-el-agua"},{"mention_id":"TIG-2015-005","locality":"Rincón de Milberg","neighborhood":"No especificado","location_description":"Sectores de Rincón de Milberg (sin calles indicadas)","event_date_as_reported":"2015-08-06","event_type":"inundación por lluvias intensas","evidence":"La misma crónica reporta ingreso de agua a viviendas en Rincón de Milberg durante el evento de lluvias; ubicación amplia.","documentary_confidence":"media","source_title":"La Arena (reporte basado en Télam y declaraciones municipales)","source_url":"https://www.laarena.com.ar/el-pais/2015-8-7-7-25-0-tigre-y-lujan-bajo-el-agua"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

insert into public.documented_episodes (id,event_date,date_precision,localities,neighborhoods,location_description,location_precision,longitude,latitude,geometry,event_type,evidence_summary,documentary_confidence,source_mentions) values ('EVT-2016-03', '2016-03-25', 'fecha de publicación; sudestada iniciada días antes', 'Delta de Tigre', 'Punta Canal', 'Paraje Punta Canal; sin calle', 'aproximada: paraje nombrado, sin dirección', NULL, NULL, NULL, 'anegamiento por sudestada y crecida', 'La Nación reporta residentes con agua hasta las rodillas y aislamiento durante la sudestada. Evento costero distinto de los anegamientos por lluvia continental.', 'media', '[{"mention_id":"TIG-2016-001","locality":"Delta de Tigre","neighborhood":"Punta Canal","location_description":"Paraje Punta Canal (sin calle indicada)","event_date_as_reported":"2016-03-25","event_type":"anegamiento por sudestada y crecida","evidence":"La Nación reporta agua hasta las rodillas, aislamiento y afectación de residentes; distingue esta observación del riesgo potencial en otros sectores.","documentary_confidence":"media","source_title":"La Nación","source_url":"https://www.lanacion.com.ar/sociedad/una-sudestada-causo-anegamientos-en-el-partido-de-tigre-nid1883301/"}]'::jsonb) on conflict (id) do update set event_date=excluded.event_date,date_precision=excluded.date_precision,localities=excluded.localities,neighborhoods=excluded.neighborhoods,location_description=excluded.location_description,location_precision=excluded.location_precision,longitude=excluded.longitude,latitude=excluded.latitude,geometry=excluded.geometry,event_type=excluded.event_type,evidence_summary=excluded.evidence_summary,documentary_confidence=excluded.documentary_confidence,source_mentions=excluded.source_mentions;

